param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop"
function Session([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)}
function Post([string]$path,[hashtable]$payload,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($payload|ConvertTo-Json -Depth 12 -Compress)}
$hq=Session "hq";$agency=Session "agency";$client=Session "client";$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$stamp=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/creative-center";$w=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh;$used=@($w.briefs|ForEach-Object {$_.abm_version_id});$source=$w.sources|Where-Object {$used -notcontains $_.abm_version_id}|Select-Object -First 1;if(-not $source){throw "Missing unused ABM version and rights-cleared country pack"}
$brief=Post "$root/briefs" @{brief_code="ROLE-CREATIVE-$stamp";brief_name="Governed role creative $stamp";objective="Create rights-safe evidence-led creative for every buying role";abm_version_id=$source.abm_version_id;country_pack_id=$source.country_pack_id;allowed_consumers=@("ads","marketing","sales","web")} $hh;$variants=@();$i=0;foreach($play in $source.plays){$i++;$v=Post "$root/briefs/$($brief.id)/variants" @{abm_play_id=$play.id;channel="display";headline="Verified value for $($play.role_name)";message_body="Evidence-led rights-safe content for $($play.role_name) decision criteria";call_to_action="Review verified evidence";ai_assisted=$true;model_reference="approved-creative-model-v1";prompt_reference="ROLE-$($play.role_code)-$stamp"} $hh;$variants+=Post "$root/variants/$($v.id)/approve" @{expected_revision=$v.revision;reference="CREATIVE-HUMAN-APPROVE-$i-$stamp"} $ah};if($variants.Count -ne $source.role_play_count){throw "Creative role coverage is incomplete"}
$published=Post "$root/briefs/$($brief.id)/publish" @{expected_revision=$brief.revision;consumers=@("ads","marketing","sales","web");delivery_reference_prefix="CREATIVE-$stamp"} $ah;$acks=@();foreach($a in $published.activations){$acks+=Post "$root/activations/$($a.id)/acknowledge" @{expected_revision=$a.revision;reference="CREATIVE-ACK-$($a.consumer)-$stamp"} $ch};$w=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh
[pscustomobject]@{project_id=$ProjectId;brief_number=$published.brief.brief_number;version_reference=$published.version.version_reference;manifest_hash=$published.version.manifest_hash;variant_count=$published.version.variant_count;role_coverage_percent=$published.version.role_coverage_percent;consumer_count=$acks.Count;acknowledged_activations=($acks|Where-Object {$_.status -eq "acknowledged"}).Count;hq=$hq.user.id;agency=$agency.user.id;client=$client.user.id;contract=$w.contract;metrics=$w.metrics}|ConvertTo-Json -Depth 8
